import{_ as o,c as e,o as d,a4 as t}from"./chunks/framework.BYxathSa.js";const h=JSON.parse('{"title":"Q5：盒模型有哪些？box-sizing 如何使用？","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/q5.md","filePath":"frontend/q5.md","lastUpdated":null}'),c={name:"frontend/q5.md"},n=t('<h1 id="q5-盒模型有哪些-box-sizing-如何使用" tabindex="-1">Q5：盒模型有哪些？<code>box-sizing</code> 如何使用？ <a class="header-anchor" href="#q5-盒模型有哪些-box-sizing-如何使用" aria-label="Permalink to &quot;Q5：盒模型有哪些？`box-sizing` 如何使用？&quot;">​</a></h1><p>盒模型是 CSS 布局的基石，由内而外：<code>content</code>（内容） → <code>padding</code>（内边距） → <code>border</code>（边框） → <code>margin</code>（外边距）。</p><ul><li><p><strong>W3C 标准盒模型（content-box）</strong><br><code>box-sizing</code> 默认为 <code>content-box</code>。此时，<code>width</code> 和 <code>height</code> 只包括内容区域，元素的实际占用宽度 = <code>width + padding + border + margin</code>。</p></li><li><p><strong>IE 怪异盒模型（border-box）</strong><br><code>box-sizing: border-box</code>。<code>width</code> 和 <code>height</code> 包括了内容、内边距和边框的尺寸。实际内容宽度 = <code>width - padding - border</code>。这种模式更符合直觉，便于控制元素整体尺寸，简化布局计算。</p></li></ul><p><strong>最佳实践</strong>：通常我们会在全局样式中设置 <code>*, *::before, *::after { box-sizing: border-box; }</code> 以避免尺寸计算混乱。</p>',4),r=[n];function i(a,s,_,b,p,g){return d(),e("div",null,r)}const x=o(c,[["render",i]]);export{h as __pageData,x as default};
